package com.obisi.store;
import android.app.*; import android.content.*; import androidx.core.app.NotificationCompat; import com.google.firebase.messaging.FirebaseMessagingService; import com.google.firebase.messaging.RemoteMessage;
public class ObisiMessagingService extends FirebaseMessagingService { public void onMessageReceived(RemoteMessage m){String title=m.getNotification()!=null?m.getNotification().getTitle():"OBISI | العبيسي";String body=m.getNotification()!=null?m.getNotification().getBody():"وصلت بضاعة جديدة";NotificationManager nm=(NotificationManager)getSystemService(Context.NOTIFICATION_SERVICE);if(android.os.Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel("obisi","OBISI",NotificationManager.IMPORTANCE_DEFAULT));nm.notify((int)System.currentTimeMillis(),new NotificationCompat.Builder(this,"obisi").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle(title).setContentText(body).setAutoCancel(true).build());}}
